const canvas=document.getElementById("pixelCanvas"),ctx=canvas.getContext("2d");canvas.width=.6*window.innerWidth,canvas.height=Math.max(120,.12*window.innerHeight);let particles=[];function drawTextToCanvas(t){const a=document.createElement("canvas"),e=a.getContext("2d");return a.width=canvas.width,a.height=canvas.height,e.fillStyle="#fff",e.font="bold 10rem VT323",e.textAlign="left",e.textBaseline="middle",e.fillText(t,0,canvas.height/2),e.getImageData(0,0,canvas.width,canvas.height)}function createParticles(t){particles=[];const a=drawTextToCanvas(t);for(let t=0;t<a.height;t+=6)for(let e=0;e<a.width;e+=6)a.data[4*(t*a.width+e)+3]>128&&particles.push({x:e+10*Math.random()-5,y:t+10*Math.random()-5,targetX:e,targetY:t,vx:0,vy:0})}function animate(){ctx.clearRect(0,0,canvas.width,canvas.height),particles.forEach(t=>{t.vx+=.01*(t.targetX-t.x),t.vy+=.01*(t.targetY-t.y),t.vx*=.9,t.vy*=.9,t.x+=t.vx,t.y+=t.vy,ctx.fillStyle="#fff",ctx.fillRect(t.x,t.y,5,5)}),requestAnimationFrame(animate)}document.fonts.ready.then(()=>{createParticles("1nf1n0t1v3r"),animate()});